const ids = []; for (const it of $input.all()) { if (!Array.isArray(it.json.keys)) throw new Error('no keys'); for (const k of it.json.keys) { const n = nm(k) || ''; if (/^components::members::profile::(introduction::)?ma_[a-z]+::/.test(n) && !/::(name|archetype)$/.test(n)) ids.push(k.key_id); } }
const out = []; for (let i = 0; i < ids.length; i += 100) out.push({ json: { n: ids.length, url: 'https://api.lokalise.com/api2/projects/31393214664f295f94dd86.76792605/keys?limit=100&include_translations=1&disable_references=1&filter_translation_lang_ids=640,767,666,1056,10154,673,757,734,733,10152,10153,749,737,760,748,708,770,754,753&filter_key_ids=' + ids.slice(i, i+100).join(',') } });
