const LING = ["47natcha@gmail.com", "arandatrad@gmail.com", "austra.muizniece@gmail.com", "boh.vozniuk@gmail.com", "bruno@bsttranslations.com", "daniel@dgmultilingualservices.com", "dmluciahorea@gmail.com", "ellen.de.venter@outlook.com", "farahputri@gmail.com", "futuremedia@sdl.com", "harald.roald@gmail.com", "ilaria.roncaglia@gmail.com", "ivanaturcin@ymail.com", "jaromirvicari@me.com", "julius.valkiunas@gmail.com", "karahansisman@gmail.com", "katri.varvikko@gmail.com", "kenneth@phraseit.dk", "marit.teichmann@gmail.com", "michal.tosza@translators.org.pl", "mjlocalize@gmail.com", "mteixeira@sacradomus.com", "mteres@terestraducciones.com", "nerissaneptuno@gmail.com", "qrcodelocalization@gmail.com", "quentinnguyen.localize@gmail.com", "root-translations@outlook.com", "roxanamoldovan25@gmail.com", "ruckova.lucia@gmail.com", "sabrathan@gmail.com", "sara.guinot.trad@gmail.com", "silis.martins@gmail.com", "silke.luehrmann@gmx.de", "straus.translations@gmail.com", "therese.svardsten@gmail.com", "translation@cornell.hu", "vidiasc@gmail.com"];
const LANGS = $('Plan').first().json.langs;
const NAMES = { es:'Spanish (Spain)', fr:'French (France)', it:'Italian', pt:'Portuguese (Brazil)', ro:'Romanian', pl:'Polish', lt:'Lithuanian', lv:'Latvian', de:'German', nl:'Dutch', da:'Danish', sv:'Swedish', no:'Norwegian Bokmål', et:'Estonian', ms:'Malay', id:'Indonesian', ko:'Korean', th:'Thai' };
const RULES = {
 de: 'Address the reader with lowercase "du/dir/dich/dein" (capitalised only at sentence start). The reader is a man. German quotes „…“. Plain spaces only. No final period on headings/labels/list fragments; period on full sentences. "Mitgliedschaft" (not Abonnement). Keep sentences short.',
 es: 'Use «» quotes. "test" never "prueba". Correct RAE accents ("aun así" without accent). Tú-form.',
 fr: 'Keep the current form of address (vous). French typography: non-breaking space (U+00A0) before : ; ? ! and inside « ». Never use dual forms like (e).',
 it: 'Use "report" (not "rapporto") for the test report, "DOC" (not OCD), "professione/professionale" (not occupazione).',
 ro: 'Use the informal "tu" form, never "dvs./dumneavoastră". Romanian quotes „…”. Prefer "incomod" to "inconfortabil".',
 th: 'Keep the current polite register. Use ตอบคำถาม/วิเคราะห์คำตอบ wording for test items and answers.',
 pl: 'Masculine forms for the reader: adjectives -y/-i, past tense -łeś/-łem, "sam".',
 lt: 'The reader is addressed with formal "Jūs": masculine SINGULAR agreement ("Jūs esate pasirengęs").',
 lv: 'The reader is addressed with formal "Jūs": masculine SINGULAR agreement ("Jūs esat pieradis").',
 pt: 'Brazilian Portuguese, "você" form.',
 nl: '', da: '', sv: '', no: '', et: '', ms: '', id: '', ko: ''
};
const nm = k => typeof k.key_name === 'object' ? (k.key_name.web || k.key_name.other) : k.key_name;
const all = []; for (const it of $input.all()) { if (!Array.isArray(it.json.keys)) throw new Error('no keys'); all.push(...it.json.keys); }
const natKey = s => s.replace(/\d+/g, d => d.padStart(4, '0'));
all.sort((a, b) => natKey(nm(a)).localeCompare(natKey(nm(b))));
const groupOf = n => { const p = n.split('::'); return p.slice(0, Math.min(p.length, 5)).join('::'); };
const out = [];
for (const iso of LANGS) {
  const groups = {};
  for (const k of all) { const en = (k.translations||[]).find(t => t.language_iso === 'en'); const tr = (k.translations||[]).find(t => t.language_iso === iso);
    if (!tr || typeof tr.translation !== 'string' || !tr.translation) continue;
    const g = groupOf(nm(k)); (groups[g] = groups[g] || []).push({ i: tr.translation_id, kid: k.key_id, key: nm(k), en: en ? en.translation : '', t: tr.translation, lock: LING.includes(tr.modified_by_email) }); }
  for (const g of Object.keys(groups)) { const items = groups[g];
    for (let j = 0; j < items.length; j += 30) { const chunk = items.slice(j, j + 30);
      if (!chunk.some(c => !c.lock)) continue;
      const sys = 'You are a senior native ' + NAMES[iso] + ' copywriter and localizer for Personality.co. You receive consecutive strings from ONE section of the Male Archetype results profile, in page order. Key names show the structure: "title" is a heading, "content" is body text, "...::start" is an intro line that is followed by "...::list::N" bullet items which continue it (e.g. an intro ending in "You:" followed by items that must grammatically follow it), faqs "title" is a question and "content" its answer. The test is ONLY for men: the reader ("you") is always a man and first-person text ("I") is spoken by a man, so every word referring to him must be masculine where the language marks gender (never dual forms like (e), /a, (-a)). TASK: return each translation so that it reads completely natural and idiomatic, as if originally written by a native copywriter — not a translation — while staying faithful to the English meaning, consistent in terminology and tone across the section, grammatically perfect, and with list items fitting their intro line. Keep archetype names exactly as currently translated. Keep placeholders such as [%1$s:x], HTML tags and line breaks exactly. Do not add or remove information. Items with "lock": true were edited by a professional linguist: return them unchanged and treat them as the style reference. If a string is already natural and correct, return it unchanged; do not rewrite just for the sake of it. ' + RULES[iso] + ' Reply with JSON only: {"items":[{"i":<id>,"t":"<string>"}]} for every input item, in the same order.';
      out.push({ json: { iso, g, n: chunk.length, body: { model: 'gpt-4.1', temperature: 0.2, response_format: { type: 'json_object' }, messages: [ { role: 'system', content: sys }, { role: 'user', content: JSON.stringify({ items: chunk.map(c => ({ i: c.i, key: c.key, en: c.en, t: c.t, lock: c.lock })) }) } ] }, src: chunk } }); } } }
return out;

const reqs = $('Build batches').all(); const res = $input.all(); const rows = []; const errs = [];
const ph = s => (s.match(/\[%\d\$s:[^\]]+\]|\{\{[^}]+\}\}|<[^>]+>/g) || []).sort().join('|');
const nl = s => (s.match(/\n/g) || []).length;
res.forEach((it, i) => { const r = reqs[i].json; let parsed = null;
  try { parsed = JSON.parse(it.json.choices[0].message.content); } catch (e) { errs.push({ iso: r.iso, g: r.g, e: String(e).slice(0,200), b: JSON.stringify(it.json).slice(0,200) }); return; }
  const m = {}; for (const x of (parsed.items||[])) m[String(x.i)] = x.t;
  for (const s of r.src) { if (s.lock) continue; const nt = m[String(s.i)]; if (typeof nt !== 'string') { errs.push({ iso: r.iso, missing: s.i }); continue; }
    if (nt === s.t) continue; const flags = [];
    if (ph(nt) !== ph(s.t)) flags.push('placeholder/html'); if (nl(nt) !== nl(s.t)) flags.push('linebreaks');
    const ratio = nt.length / Math.max(1, s.t.length); if (ratio > 1.6 || ratio < 0.5) flags.push('length');
    rows.push({ iso: r.iso, tid: s.i, kid: s.kid, key: s.key, en: s.en, old: s.t, new: nt, flags }); } });
return [{ json: { n: rows.length, errs, rows } }];
